function parseMessageContent(value: string): ParsedMessageContent {
  value = readForwardedContent(value)?.content ?? value;
  if (!value) return { kind: "text", text: "" };

  if (value.startsWith(MEDIA_PREFIX)) {
    try {
      const parsed = JSON.parse(value.slice(MEDIA_PREFIX.length)) as {
        type?: string;
        text?: string;
        src?: string;
        latitude?: number;
        longitude?: number;
        label?: string;
        mapUrl?: string;
        previewUrl?: string;
        items?: Array<{ src?: string; kind?: "image" | "video"; durationMs?: number }>;
        url?: string;
        name?: string;
        size?: number;
        mimeType?: string;
        title?: string;
        author?: string;
        coverUrl?: string;
        caption?: string;
        mode?: "note" | "file";
        source?: "greeting_button" | "picker";
        durationMs?: number;
        waveform?: number[];
        storyId?: string;
        authorName?: string;
        previewText?: string;
        isOwn?: boolean;
        question?: string;
        options?: string[];
        quizMode?: boolean;
        correctOptionIndex?: number | null;
        expiresAt?: string | null;
      };
      if (parsed.type === "story_reply") {
        return {
          kind: "story_reply",
          text: parsed.text?.trim() ?? "",
          authorName: parsed.authorName?.trim() || "История",
          storyId: parsed.storyId?.trim() || undefined,
          previewText: parsed.previewText?.trim() || undefined,
          isOwn: Boolean(parsed.isOwn),
        };
      }
      if (parsed.type === "sticker" && parsed.src) {
        const rawEmoji = "emoji" in parsed && typeof parsed.emoji === "string" ? parsed.emoji : undefined;
        return {
          kind: "sticker",
          src: parsed.src,
          source: parsed.source,
          emoji: rawEmoji || getStickerEmojiBySrc(parsed.src),
        };
      }
      if (parsed.type === "image" && parsed.src && (isImagePayload(parsed.src) || isRenderableMediaUrl(parsed.src))) {
        return {
          kind: "image",
          src: parsed.src,
          caption: parsed.caption?.trim() ?? "",
        };
      }
      if (
        parsed.type === "poll" &&
        typeof parsed.question === "string" &&
        Array.isArray(parsed.options)
      ) {
        return {
          kind: "poll",
          question: parsed.question,
          options: parsed.options,
          quizMode: Boolean(parsed.quizMode),
          correctOptionIndex: typeof parsed.correctOptionIndex === "number" ? parsed.correctOptionIndex : null,
          expiresAt: typeof parsed.expiresAt === "string" ? parsed.expiresAt : null,
        };
      }
      if (parsed.type === "album" && Array.isArray(parsed.items) && parsed.items.length > 0) {
        const items: Array<{ src: string; kind: "image" | "video"; durationMs?: number }> = parsed.items
          .slice(0, MAX_MEDIA_ALBUM_ITEMS)
          .map((item) => {
            if (!item?.src || !isRenderableMediaUrl(item.src)) return null;
            const kind = item.kind === "video" ? "video" : "image";
            if (kind === "video") {
              return {
                src: item.src,
                kind,
                durationMs: Math.max(0, Number(item.durationMs) || 0),
              };
            }
            return {
              src: item.src,
              kind,
            };
          })
          .filter(Boolean) as Array<{ src: string; kind: "image" | "video"; durationMs?: number }>;
        if (items.length > 0) {
          return {
            kind: "album",
            items,
            caption: parsed.caption?.trim() ?? "",
          };
        }
      }
      if (parsed.type === "voice" && parsed.src && (isAudioPayload(parsed.src) || isRenderableMediaUrl(parsed.src))) {
        const waveform = Array.isArray(parsed.waveform)
          ? parsed.waveform
            .map((value: unknown) => Number(value))
            .filter((value: number) => Number.isFinite(value))
            .map((value: number) => Math.min(100, Math.max(0, Math.round(value))))
          : undefined;
        return {
          kind: "voice",
          src: parsed.src,
          durationMs: Math.max(0, Number(parsed.durationMs) || 0),
          waveform: waveform?.length ? waveform : undefined,
        };
      }
      if (parsed.type === "video" && parsed.src && (isVideoPayload(parsed.src) || isRenderableMediaUrl(parsed.src))) {
        return {
          kind: "video",
          src: parsed.src,
          durationMs: Math.max(0, Number(parsed.durationMs) || 0),
          caption: parsed.caption?.trim() ?? "",
          mode: parsed.mode === "file" ? "file" : "note",
        };
      }
      if (parsed.type === "file" && parsed.src && isRenderableMediaUrl(parsed.src)) {
        const fallbackName = parsed.src.split("/").pop() || "Файл";
        return {
          kind: "file",
          src: parsed.src,
          name: (parsed.name?.trim() || fallbackName).slice(0, 180),
          size: Math.max(0, Number(parsed.size) || 0),
          mimeType: parsed.mimeType?.trim() || "application/octet-stream",
          caption: parsed.caption?.trim() ?? "",
        };
      }
      if (
        parsed.type === "music" &&
        parsed.url &&
        (isRenderableMediaUrl(parsed.url) || parsed.url.startsWith("data:audio/"))
      ) {
        const title = parsed.title?.trim() || deriveMusicLabel(parsed.url);
        const caption = parsed.caption?.trim() || "";
        const legacyLabel = parsed.label?.trim() || "";
        return {
          kind: "music",
          url: parsed.url,
          title,
          caption: caption || (legacyLabel && legacyLabel !== title ? legacyLabel : ""),
          author: typeof parsed.author === "string" ? parsed.author.trim().slice(0, 300) : undefined,
          coverUrl: typeof parsed.coverUrl === "string" && isRenderableMediaUrl(parsed.coverUrl) ? parsed.coverUrl : undefined,
          durationMs: typeof parsed.durationMs === "number" && Number.isFinite(parsed.durationMs) ? Math.max(0, parsed.durationMs) : undefined,
        };
      }
    } catch {
      const emojiInfo = getEmojisInfo(value);
      return {
        kind: "text",
        text: value,
        isSingleEmoji: emojiInfo.isOnly && emojiInfo.count === 1,
        isOnlyEmojis: emojiInfo.isOnly,
        emojiCount: emojiInfo.count
      };
    }
  }

  if (isImagePayload(value)) {
    return { kind: "image", src: value, caption: "" };
  }

  const emojiInfo = getEmojisInfo(value);
  return {
    kind: "text",
    text: value,
    isSingleEmoji: emojiInfo.isOnly && emojiInfo.count === 1,
    isOnlyEmojis: emojiInfo.isOnly,
    emojiCount: emojiInfo.count
  };
}

function formatAddressFromNominatim(raw: unknown) {
  if (!raw || typeof raw !== "object") return null;
  const address = (raw as { address?: Record<string, unknown> }).address;
  const displayName = (raw as { display_name?: unknown }).display_name;
  if (!address || typeof address !== "object") {
    if (typeof displayName === "string" && displayName.trim()) {
      return displayName.split(",").slice(0, 2).join(", ").trim() || null;
    }
    return null;
  }

  const roadCandidates = ["road", "pedestrian", "footway", "path", "residential"] as const;
  const localityCandidates = ["city", "town", "village", "hamlet", "suburb", "city_district", "county"] as const;
  const road = roadCandidates
    .map((key) => address[key])
    .find((value) => typeof value === "string" && value.trim());
  const houseNumber = address.house_number;
  const locality = localityCandidates
    .map((key) => address[key])
    .find((value) => typeof value === "string" && value.trim());

  const roadText = typeof road === "string" ? road.trim() : "";
  const houseText = typeof houseNumber === "string" ? houseNumber.trim() : "";
  const localityText = typeof locality === "string" ? locality.trim() : "";

  const primary = [roadText, houseText].filter(Boolean).join(", ");
  if (primary && localityText) {
    return `${primary}, ${localityText}`;
  }
  if (primary) return primary;
  if (localityText) return localityText;

  if (typeof displayName === "string" && displayName.trim()) {
    return displayName.split(",").slice(0, 2).join(", ").trim() || null;
  }
  return null;
}

async function resolveLocationAddress(latitude: number, longitude: number) {
  if (typeof fetch !== "function") return null;
  const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
  const timeout = setTimeout(() => controller?.abort(), 4500);
  try {
    const query = new URLSearchParams({
      format: "jsonv2",
      lat: String(latitude),
      lon: String(longitude),
      zoom: "18",
      addressdetails: "1",
      "accept-language": "ru",
    });
    const response = await fetch(`https://nominatim.openstreetmap.org/reverse?${query.toString()}`, {
      method: "GET",
      headers: { Accept: "application/json" },
      cache: "no-store",
      signal: controller?.signal,
    });
    if (!response.ok) return null;
    const data = (await response.json()) as unknown;
    return formatAddressFromNominatim(data);
  } catch {
    return null;
  } finally {
    clearTimeout(timeout);
  }
}

function albumGridContainerClass(count: number) {
  if (count === 2) return "grid grid-cols-1 gap-[2px]";
  if (count === 3) return "grid grid-cols-2 gap-[2px]";
  if (count === 4) return "grid grid-cols-3 gap-[2px]";
  if (count === 5) return "grid grid-cols-6 gap-[2px]";
  return "grid grid-cols-6 gap-[2px]";
}

function albumGridItemClass(count: number, index: number) {
  if (count === 2) {
    return "col-span-1 aspect-[16/9]";
  }
  if (count === 3) {
    return index === 0 ? "col-span-2 aspect-[16/9]" : "col-span-1 aspect-square";
  }
  if (count === 4) {
    return index === 0 ? "col-span-3 aspect-[16/9]" : "col-span-1 aspect-square";
  }
  if (count === 5) {
    return index < 2 ? "col-span-3 aspect-[16/9]" : "col-span-2 aspect-square";
  }
  // 6 items: 2 rows, 3 items per row
  return "col-span-2 aspect-square";
}

