function getSupportedVideoRecorderMimeType() {
  if (typeof MediaRecorder === "undefined" || typeof MediaRecorder.isTypeSupported !== "function") {
    return null;
  }
  const isAppleWebKit =
    typeof navigator !== "undefined" &&
    /AppleWebKit/i.test(navigator.userAgent) &&
    !/Chrome|Chromium|Edg|OPR|Firefox/i.test(navigator.userAgent);
  if (isAppleWebKit) {
    const appleCandidates = [
      "video/mp4;codecs=h264,aac",
      "video/mp4;codecs=avc1,mp4a.40.2",
      "video/mp4",
    ];
    for (const type of appleCandidates) {
      if (MediaRecorder.isTypeSupported(type)) return type;
    }
  }
  const candidates = [
    "video/webm;codecs=vp8,opus",
    "video/webm;codecs=vp9,opus",
    "video/webm",
    "video/mp4;codecs=h264,aac",
    "video/mp4",
  ];
  for (const type of candidates) {
    if (MediaRecorder.isTypeSupported(type)) return type;
  }
  return null;
}

function getSupportedAudioRecorderMimeType() {
  if (typeof MediaRecorder === "undefined" || typeof MediaRecorder.isTypeSupported !== "function") {
    return null;
  }
  const isAppleWebKit =
    typeof navigator !== "undefined" &&
    /AppleWebKit/i.test(navigator.userAgent) &&
    !/Chrome|Chromium|Edg|OPR|Firefox/i.test(navigator.userAgent);
  if (isAppleWebKit) {
    return MediaRecorder.isTypeSupported("audio/mp4") ? "audio/mp4" : null;
  }
  const candidates = [
    "audio/webm;codecs=opus",
    "audio/webm",
    "audio/ogg;codecs=opus",
    "audio/mp4",
  ];
  for (const type of candidates) {
    if (MediaRecorder.isTypeSupported(type)) return type;
  }
  return null;
}

function createAudioRecorder(stream: MediaStream) {
  const preferredMimeType = getSupportedAudioRecorderMimeType();
  const optionCandidates: MediaRecorderOptions[] = [];
  if (preferredMimeType) {
    optionCandidates.push(
      { mimeType: preferredMimeType, audioBitsPerSecond: 256_000 },
      { mimeType: preferredMimeType, audioBitsPerSecond: 192_000 },
      { mimeType: preferredMimeType, audioBitsPerSecond: 128_000 },
      { mimeType: preferredMimeType },
    );
  }
  optionCandidates.push(
    { audioBitsPerSecond: 256_000 },
    { audioBitsPerSecond: 192_000 },
    { audioBitsPerSecond: 128_000 },
    {},
  );

  for (const options of optionCandidates) {
    try {
      return new MediaRecorder(stream, options);
    } catch {
      // try next fallback
    }
  }
  throw new Error("audio_recorder_unsupported");
}

function createVideoRecorder(stream: MediaStream) {
  const preferredMimeType = getSupportedVideoRecorderMimeType();
  const optionCandidates: MediaRecorderOptions[] = [];
  if (preferredMimeType) {
    optionCandidates.push(
      {
        mimeType: preferredMimeType,
        videoBitsPerSecond: 3_000_000,
        audioBitsPerSecond: 128_000,
      },
      {
        mimeType: preferredMimeType,
        videoBitsPerSecond: 2_000_000,
        audioBitsPerSecond: 128_000,
      },
      { mimeType: preferredMimeType },
    );
  }
  optionCandidates.push(
    {
      videoBitsPerSecond: 3_000_000,
      audioBitsPerSecond: 128_000,
    },
    {
      videoBitsPerSecond: 2_000_000,
      audioBitsPerSecond: 128_000,
    },
    {},
  );

  for (const options of optionCandidates) {
    try {
      return new MediaRecorder(stream, options);
    } catch {
      // try next fallback
    }
  }
  throw new Error("video_recorder_unsupported");
}

function formatMediaDuration(durationMs: number) {
  const safeDuration = Math.max(0, Math.floor(durationMs));
  const totalSeconds = Math.floor(safeDuration / 1000);
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  const centiseconds = Math.floor((safeDuration % 1000) / 10);
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}:${String(centiseconds).padStart(2, "0")}`;
}

function formatDurationFromSeconds(secondsInput: number) {
  const totalSeconds = Math.max(0, Math.floor(secondsInput));
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}`;
}

function formatMediaViewerDate(iso: string) {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return "";
  return date.toLocaleString(dateLocale(), {
    day: "numeric",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
  });
}


async function probeBlobDurationMs(blob: Blob, mediaKind: "audio" | "video") {
  if (typeof window === "undefined") return 0;
  return await new Promise<number>((resolve) => {
    const element = document.createElement(mediaKind);
    const objectUrl = URL.createObjectURL(blob);
    let settled = false;
    const cleanup = () => {
      if (settled) return;
      settled = true;
      element.removeAttribute("src");
      try {
        element.load();
      } catch {
        // ignore
      }
      URL.revokeObjectURL(objectUrl);
    };
    const finish = (value: number) => {
      cleanup();
      resolve(Math.max(0, Math.round(value)));
    };
    const timeoutId = window.setTimeout(() => finish(0), 3000);
    const clearTimer = () => window.clearTimeout(timeoutId);
    element.preload = "metadata";
    element.onloadedmetadata = () => {
      if (element.duration === Infinity) {
        element.currentTime = 1e101;
        element.ontimeupdate = () => {
          element.ontimeupdate = null;
          element.currentTime = 0;
          clearTimer();
          const d = Number.isFinite(element.duration) ? element.duration : 0;
          finish(d > 0 ? d * 1000 : 0);
        };
        return;
      }
      clearTimer();
      const durationSeconds = Number.isFinite(element.duration) ? element.duration : 0;
      finish(durationSeconds > 0 ? durationSeconds * 1000 : 0);
    };
    element.onerror = () => {
      clearTimer();
      finish(0);
    };
    element.src = objectUrl;
  });
}

async function flushRecorderThenStop(recorder: MediaRecorder, drainMs = 0) {
  if (recorder.state === "inactive") return;
  if (drainMs > 0) {
    await new Promise<void>((resolve) => {
      window.setTimeout(() => resolve(), drainMs);
    });
  }
  try {
    if (recorder.state === "recording") {
      recorder.requestData();
    }
  } catch {
    // ignore
  }
  try {
    recorder.stop();
  } catch {
    // ignore
  }
}

const SUPPORTED_IMAGE_TYPES = new Set(["image/jpeg", "image/png", "image/webp", "image/gif"]);
const HEIC_IMAGE_TYPES = new Set(["image/heic", "image/heif", "image/heic-sequence", "image/heif-sequence"]);
const AUDIO_MAX_BYTES = 100 * 1024 * 1024;
const FILE_MAX_BYTES = 100 * 1024 * 1024;
const AUDIO_MAX_DURATION_MS = 600_000;
const MESSAGE_LINK_RE = /((?:https?:\/\/)?(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}(?:\/[^\s]*)?)/giu;
const LINK_TRAILING_PUNCT_RE = /[),.!?:;]+$/u;
const TRUSTED_LINK_DOMAINS = new Set(["eclpse.ru", "eclpse.online"]);
const PUBLIC_LINK_RE = /^[a-z0-9_]{2,32}$/iu;
const VOICE_PLAY_EVENT = "eclipse:voice-play";
const VOICE_STATE_EVENT = "eclipse:voice-state";

// type MessageTextSegment = imported from "./types"

function normalizeExternalUrl(value: string) {
  if (/^https?:\/\//iu.test(value)) return value;
  return `https://${value}`;
}

function isTrustedLinkHost(hostname: string) {
  const host = hostname.toLowerCase();
  for (const trusted of TRUSTED_LINK_DOMAINS) {
    if (host === trusted || host.endsWith(`.${trusted}`)) return true;
  }
  return false;
}

function isLikelyPublicLink(link?: string | null) {
  if (!link) return false;
  return PUBLIC_LINK_RE.test(link);
}


function splitMessageTextSegments(value: string): MessageTextSegment[] {
  if (!value) return [{ kind: "text", text: "" }];
  const segments: MessageTextSegment[] = [];
  const candidates: Array<{ index: number; raw: string; kind: "url" }> = [];
  for (const match of value.matchAll(MESSAGE_LINK_RE)) {
    const index = match.index ?? -1;
    const raw = match[0] ?? "";
    if (index >= 0 && raw) candidates.push({ index, raw, kind: "url" });
  }
  candidates.sort((a, b) => a.index - b.index);
  let cursor = 0;
  for (const candidate of candidates) {
    const index = candidate.index;
    const full = candidate.raw;
    if (index < cursor) continue;
    if (index > cursor) {
      segments.push({ kind: "text", text: value.slice(cursor, index) });
    }
    let tokenText = full;
    const trailing = tokenText.match(LINK_TRAILING_PUNCT_RE)?.[0] ?? "";
    if (trailing) {
      tokenText = tokenText.slice(0, -trailing.length);
    }
    if (tokenText) {
      segments.push({ kind: "url", text: tokenText, url: normalizeExternalUrl(tokenText) });
    }
    if (trailing) {
      segments.push({ kind: "text", text: trailing });
    }
    cursor = index + full.length;
  }
  if (cursor < value.length) {
    segments.push({ kind: "text", text: value.slice(cursor) });
  }
  return segments.length > 0 ? segments : [{ kind: "text", text: value }];
}

function formatFileSize(size: number) {
  const safeSize = Math.max(0, size);
  if (safeSize >= 1024 * 1024) {
    return `${(safeSize / (1024 * 1024)).toFixed(1)} MB`;
  }
  if (safeSize >= 1024) {
    return `${Math.round(safeSize / 1024)} KB`;
  }
  return `${safeSize} B`;
}
