const PRESENCE_STATUS_TICK_MS = 15_000;

let cp1251ReverseMapCache: Map<string, number> | null = null;

function getCp1251ReverseMap() {
  if (cp1251ReverseMapCache) return cp1251ReverseMapCache;
  const map = new Map<string, number>();
  try {
    const decoder = new TextDecoder("windows-1251");
    for (let i = 0; i <= 255; i += 1) {
      map.set(decoder.decode(Uint8Array.of(i)), i);
    }
  } catch {
    for (let i = 0; i <= 0x7f; i += 1) {
      map.set(String.fromCharCode(i), i);
    }
  }
  cp1251ReverseMapCache = map;
  return map;
}

function cp1251ByteFromChar(char: string): number | null {
  const map = getCp1251ReverseMap();
  const value = map.get(char);
  return value ?? null;
}

function tryDecodeCp1251Mojibake(input: string) {
  if (!input) return input;
  const bytes: number[] = [];
  for (const char of input) {
    const cp = cp1251ByteFromChar(char);
    if (cp === null) return input;
    bytes.push(cp);
  }
  let decoded = "";
  try {
    decoded = new TextDecoder("utf-8", { fatal: false }).decode(new Uint8Array(bytes));
  } catch {
    return input;
  }
  if (!decoded || decoded.includes("\uFFFD")) return input;

  const badPattern = /[\u0420\u0421][\u0410-\u042f\u0430-\u044f\u0401\u0451]/g;
  const originalBad = (input.match(badPattern) || []).length;
  const decodedBad = (decoded.match(badPattern) || []).length;
  const originalCyr = (input.match(/[\u0410-\u042f\u0430-\u044f\u0401\u0451]/g) || []).length;
  const decodedCyr = (decoded.match(/[\u0410-\u042f\u0430-\u044f\u0401\u0451]/g) || []).length;

  if (decodedBad < originalBad && decodedCyr >= originalCyr) {
    return decoded;
  }
  if (originalBad > 0 && decodedBad === 0 && decodedCyr > 0) {
    return decoded;
  }
  return input;
}

function normalizeMojibakeTokens(input: string) {
  let value = tryDecodeCp1251Mojibake(input);
  for (const [broken, fixed] of MOJIBAKE_TOKEN_FIXES) {
    if (value.includes(broken)) {
      value = value.split(broken).join(fixed);
    }
  }
  return value;
}

function normalizeLastMessagePreview(value: string) {
  const normalized = normalizeMojibakeTokens(value || "");
  const parsed = parseMessageContent(normalized);
  if (parsed.kind === "story_reply") {
    return parsed.text ? t("Ответ на историю: {0}", { 0: parsed.text }) : t("Ответ на историю");
  }
  if (parsed.kind === "sticker") {
    return t("Стикер");
  }
  if (parsed.kind === "image") {
    return parsed.caption ? t("Фотография: {0}", { 0: parsed.caption }) : t("Фотография");
  }
  if (parsed.kind === "poll") {
    return t("Опрос: {0}", { 0: parsed.question });
  }
  if (parsed.kind === "album") {
    return parsed.caption ? t("Альбом: {0}", { 0: parsed.caption }) : getAlbumPreviewLabel(parsed.items);
  }
  if (parsed.kind === "voice") {
    return t("Голосовое сообщение");
  }
  if (parsed.kind === "video") {
    if (parsed.mode === "file") {
      return parsed.caption ? t("Видео: {0}", { 0: parsed.caption }) : t("Видеозапись");
    }
    return t("Видеосообщение");
  }
  if (parsed.kind === "file") {
    return parsed.name ? (parsed.caption ? `${parsed.name} — ${parsed.caption}` : parsed.name) : t("Файл");
  }
  if (parsed.kind === "music") {
    return parsed.title ? (parsed.caption ? `${parsed.title} — ${parsed.caption}` : parsed.title) : t("Музыка");
  }
  const plainText = parsed.text || "";
  if (plainText.startsWith("📊 Опрос:") || plainText.startsWith("Опрос:") || plainText.startsWith("Викторина:")) {
    let question = "";
    if (plainText.startsWith("📊 Опрос:")) {
      question = plainText.slice("📊 Опрос:".length).trim();
    } else if (plainText.startsWith("Опрос:")) {
      question = plainText.slice("Опрос:".length).trim();
    } else {
      question = plainText.slice("Викторина:".length).trim();
    }
    return question;
  }

  return plainText;
}

let chatCacheGeneration = 0;
const legacyMediaGrantAttempts = new Map<string, number>();
const parsedMessageCache = new Map<string, ParsedMessageContent>();
function parseMessageContentCached(value: string, resolveMedia = true) {
  const key = value || "";
  if (key.length > 4096) {
    const parsed = parseMessageContent(key);
    return resolveMedia ? resolveMessageMedia(parsed) : parsed;
  }
  const cached = parsedMessageCache.get(key);
  if (cached) return resolveMedia ? resolveMessageMedia(cached) : cached;
  const parsed = parseMessageContent(key);
  if (parsedMessageCache.size > PARSED_MESSAGE_CACHE_MAX) {
    parsedMessageCache.clear();
  }
  parsedMessageCache.set(key, parsed);
  return resolveMedia ? resolveMessageMedia(parsed) : parsed;
}

function getEditableTextFromParsed(parsed: ParsedMessageContent) {
  if (parsed.kind === "image") return parsed.caption;
  if (parsed.kind === "video") return parsed.caption;
  if (parsed.kind === "file") return parsed.caption;
  if (parsed.kind === "music") return parsed.caption;
  if (parsed.kind === "text") return parsed.text;
  return "";
}

function buildEditedMessagePayload(target: EditTarget, draftText: string) {
  const caption = draftText.trim();
  if (target.kind === "text") {
    return caption;
  }
  if (target.kind === "image" && target.src) {
    return `${MEDIA_PREFIX}${JSON.stringify({
      type: "image",
      src: target.src,
      caption,
    })}`;
  }
  if (target.kind === "video" && target.src) {
    return `${MEDIA_PREFIX}${JSON.stringify({
      type: "video",
      src: target.src,
      durationMs: Math.max(0, Math.round(target.durationMs ?? 0)),
      caption,
      mode: target.mode === "note" ? "note" : "file",
    })}`;
  }
  if (target.kind === "music" && target.url) {
    return serializeMusicContent(target.url, target.title?.trim() || "Музыка", caption, target);
  }
  if (target.kind === "file" && target.src) {
    return `${MEDIA_PREFIX}${JSON.stringify({
      type: "file",
      src: target.src,
      name: target.name?.trim() || "Файл",
      size: Math.max(0, Math.round(target.size ?? 0)),
      mimeType: target.mimeType?.trim() || "application/octet-stream",
      caption,
    })}`;
  }
  return caption;
}

function hasDetachedMessageAnnotations(parsed: ParsedMessageContent) {
  return parsed.kind === "sticker" || parsed.kind === "text" && parsed.isOnlyEmojis ||
    parsed.kind === "video" && (parsed.mode !== "file" || !parsed.caption) ||
    (parsed.kind === "image" || parsed.kind === "album") && !parsed.caption;
}

function canEditMessageContent(parsed: ParsedMessageContent) {
  if (parsed.kind === "voice" || parsed.kind === "sticker") return false;
  if (parsed.kind === "video" && parsed.mode === "note") return false;
  return (
    parsed.kind === "text" ||
    parsed.kind === "image" ||
    parsed.kind === "video" ||
    parsed.kind === "file" ||
    parsed.kind === "music"
  );
}

function canEditMessage(message: DecryptedMessage, parsed: ParsedMessageContent, isMine: boolean) {
  if (!isMine) return false;
  const createdAtMs = Date.parse(message.createdAt);
  if (Number.isNaN(createdAtMs) || Date.now() - createdAtMs > MESSAGE_EDIT_WINDOW_MS) {
    return false;
  }
  return canEditMessageContent(parsed);
}

const normalizedPreviewCache = new Map<string, string>();
function normalizeLastMessagePreviewCached(value: string) {
  const key = value || "";
  const cacheKey = `${dateLocale()}|${key}`;
  if (key.length > 1024) {
    return normalizeLastMessagePreview(key);
  }
  const cached = normalizedPreviewCache.get(cacheKey);
  if (cached) return cached;
  const normalized = normalizeLastMessagePreview(key);
  if (normalizedPreviewCache.size > NORMALIZED_PREVIEW_CACHE_MAX) {
    normalizedPreviewCache.clear();
  }
  normalizedPreviewCache.set(cacheKey, normalized);
  return normalized;
}

const GROUP_NAME_COLORS = ["text-sky-400", "text-pink-400", "text-orange-400", "text-green-400"] as const;
function pickGroupNameColor(seed?: string | null) {
  if (!seed) return GROUP_NAME_COLORS[0];
  let hash = 0;
  for (let i = 0; i < seed.length; i += 1) {
    hash = (hash * 31 + seed.charCodeAt(i)) % GROUP_NAME_COLORS.length;
  }
  return GROUP_NAME_COLORS[hash];
}

const chatListPreviewMetaCache = new Map<string, ChatListPreviewMeta>();
function resolveChatListPreviewMetaCached(input: unknown) {
  const key = typeof input === "string" ? input : (input && typeof input === "object" && "text" in input && typeof (input as any).text === "string" ? (input as any).text : "");
  const cacheKey = `${dateLocale()}|${key}`;
  const cached = chatListPreviewMetaCache.get(cacheKey);
  if (cached) return cached;
  const resolved = resolveChatListPreviewMeta(key);
  if (chatListPreviewMetaCache.size > CHAT_LIST_PREVIEW_META_CACHE_MAX) {
    chatListPreviewMetaCache.clear();
  }
  chatListPreviewMetaCache.set(cacheKey, resolved);
  return resolved;
}

const messageTimeLabelCache = new Map<string, string>();
function formatMessageTimeLabel(iso: string) {
  const key = iso || "";
  const cached = messageTimeLabelCache.get(key);
  if (cached) return cached;
  const target = new Date(iso || "");
  const label = Number.isNaN(target.getTime())
    ? ""
    : target.toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
      hourCycle: "h23",
    });
  if (messageTimeLabelCache.size > MESSAGE_TIME_LABEL_CACHE_MAX) {
    messageTimeLabelCache.clear();
  }
  messageTimeLabelCache.set(key, label);
  return label;
}

function formatForwardMessageCount(count: number): string {
  return plural(count, ["сообщение", "сообщения", "сообщений"], "message");
}

function resolveStackedBubbleShape(input: {
  isMine: boolean;
  chainWithPrevious: boolean;
  chainWithNext: boolean;
}) {
  const base = "rounded-[16px]";
  if (input.isMine) {
    if (input.chainWithPrevious && input.chainWithNext) {
      return `${base} rounded-tr-[5px] rounded-br-[5px]`;
    }
    if (input.chainWithPrevious) {
      return `${base} rounded-tr-[5px] rounded-br-none`;
    }
    if (input.chainWithNext) {
      return `${base} rounded-br-[5px]`;
    }
    return `${base} rounded-br-none`;
  }
  // Incoming
  if (input.chainWithPrevious && input.chainWithNext) {
    return `${base} rounded-tl-[5px] rounded-bl-[5px]`;
  }
  if (input.chainWithPrevious) {
    return `${base} rounded-tl-[5px] rounded-bl-none`;
  }
  if (input.chainWithNext) {
    return `${base} rounded-bl-[5px]`;
  }
  return `${base} rounded-bl-none`;
}

function resolveStackedMediaShape(input: {
  isMine: boolean;
  chainWithPrevious: boolean;
  chainWithNext: boolean;
}) {
  const base = "rounded-[20px]";
  if (input.isMine) {
    if (input.chainWithPrevious && input.chainWithNext) {
      return `${base} rounded-tr-[6px] rounded-br-[6px]`;
    }
    if (input.chainWithPrevious) {
      return `${base} rounded-tr-[6px]`;
    }
    if (input.chainWithNext) {
      return `${base} rounded-br-[6px]`;
    }
    return base;
  }
  // Incoming
  if (input.chainWithPrevious && input.chainWithNext) {
    return `${base} rounded-tl-[6px] rounded-bl-[6px]`;
  }
  if (input.chainWithPrevious) {
    return `${base} rounded-tl-[6px]`;
  }
  if (input.chainWithNext) {
    return `${base} rounded-bl-[6px]`;
  }
  return base;
}

