const dayKeyCache = new Map<string, string>();
const messageDayLabelCache = new Map<string, string>();

function dayKeyFromIso(iso: string) {
  const cached = dayKeyCache.get(iso);
  if (cached !== undefined) return cached;
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) {
    dayKeyCache.set(iso, "");
    return "";
  }
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  const key = `${year}-${month}-${day}`;
  if (dayKeyCache.size > DAY_KEY_CACHE_MAX) {
    dayKeyCache.clear();
  }
  dayKeyCache.set(iso, key);
  return key;
}

function formatMessageDayLabel(iso: string) {
  const todayKey = dayKeyFromIso(new Date().toISOString());
  const cacheKey = `${dateLocale()}|${todayKey}|${iso}`;
  const cached = messageDayLabelCache.get(cacheKey);
  if (cached !== undefined) return cached;

  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) {
    messageDayLabelCache.set(cacheKey, "");
    return "";
  }

  const now = new Date();
  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  const yesterdayKey = dayKeyFromIso(yesterday.toISOString());
  const currentKey = dayKeyFromIso(iso);

  if (currentKey === todayKey) {
    messageDayLabelCache.set(cacheKey, t("Сегодня"));
    return t("Сегодня");
  }
  if (currentKey === yesterdayKey) {
    messageDayLabelCache.set(cacheKey, t("Вчера"));
    return t("Вчера");
  }

  const sameYear = date.getFullYear() === now.getFullYear();
  const label = date.toLocaleDateString(dateLocale(), sameYear
    ? { day: "numeric", month: "long" }
    : { day: "numeric", month: "long", year: "numeric" });
  if (messageDayLabelCache.size > MESSAGE_DAY_LABEL_CACHE_MAX) {
    messageDayLabelCache.clear();
  }
  messageDayLabelCache.set(cacheKey, label);
  return label;
}

function hashSeed(input: string) {
  let h = 2166136261;
  for (let i = 0; i < input.length; i += 1) {
    h ^= input.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

function buildDissolveParticles(seedInput: string, count = 36): DissolveParticle[] {
  let seed = hashSeed(seedInput);
  const next = () => {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    return seed / 0xffffffff;
  };

  return Array.from({ length: count }, () => {
    const rVar = next();
    const variant: "primary" | "light" | "sparkle" =
      rVar < 0.45 ? "primary" : rVar < 0.8 ? "light" : "sparkle";
    return {
      x: Math.round(5 + next() * 90),
      y: Math.round(8 + next() * 84),
      dx: Math.round((next() - 0.5) * 52),
      dy: Math.round(-10 - next() * 32),
      size: Number((1.2 + next() * 1.4).toFixed(1)),
      delay: Number((next() * 0.05).toFixed(3)),
      variant,
    };
  });
}

