      const result = await apiRequest<{ group: { name: string; description: string | null; avatarUrl: string | null } }>("/api/groups/" + encodeURIComponent(entity.link), { method: "PATCH", body: JSON.stringify(payload) });
      const updated = { ...groupModalData!, group: { ...entity, ...result.group } };
